import json


def parse(text: str):
    try:
        value = json.loads(text)
    except (TypeError, ValueError):
        return []
    return value if isinstance(value, list) else []

def validate(events: list):
    valid = []
    for event in events:
        if not isinstance(event, dict):
            continue
        sku = event.get("sku")
        delta = event.get("delta")
        if isinstance(sku, str) and sku.strip() and isinstance(delta, int) and not isinstance(delta, bool):
            valid.append({"sku": sku, "delta": delta})
    return valid

def aggregate(events: list):
    balances = {}
    for event in events:
        sku = event["sku"]
        balances[sku] = balances.get(sku, 0) + event["delta"]
    return balances
